import { useCallback, useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  label?: string;
  placeholder?: string;
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  value,
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = value ?? internalTags;

  const commit = useCallback(
    (next: string[]) => {
      const normalized = next
        .map((tag) => tag.trim())
        .filter((tag, index, all) => tag !== '' && all.indexOf(tag) === index);

      if (value === undefined) {
        setInternalTags(normalized);
      }
      onChange?.(normalized);
    },
    [onChange, value],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '10px',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <span style={{ fontSize: '13px', color: 'var(--jx-text-2)' }}>{label}</span>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={commit}
      />

      {tags.length === 0 ? (
        <span style={{ fontSize: '13px', color: 'var(--jx-text-3)' }}>
          Теги пока не выбраны
        </span>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip
              key={tag}
              removable
              onRemove={() => commit(tags.filter((item) => item !== tag))}
            >
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

